265	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
266	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
267	
268	    /**
269	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
270	     * code are kept when present; otherwise country code '+61' is assumed and a single
271	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
272	     * stripped. The result must be a '+' followed by 8 to 15 digits.
273	     * Returns {@code null} when the number cannot form a valid E.164 value.
274	     */
275	    private static String normalizeTelephone(String telephone) {
276	        if (telephone == null) {
277	            return null;
278	        }
279	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
280	        String e164;
281	        if (cleaned.startsWith("+")) {
282	            e164 = cleaned;
283	        } else {
284	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
285	            e164 = "+61" + national;
286	        }
287	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
288	    }
289	
290	    /**
291	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
292	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
293	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
294	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
295	     */
296	    private String generateCustomerCode(String city, String lastName) {
297	        String city3 = firstThreeLetters(city);
298	        String last3 = firstThreeLetters(lastName);
299	        int sequence = countOwnersInCity(city) + 1;
300	        return String.format("%s-%s-%04d", city3, last3, sequence);
301	    }
302	
303	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
304	    private static String firstThreeLetters(String value) {
305	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
306	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
307	    }
308	
309	    /**
310	     * The number of existing owners registered in {@code city}, compared case-insensitively
311	     * with collapsed whitespace.
312	     */
313	    private int countOwnersInCity(String city) {
314	        String normalized = normalizeHouseholdField(city);
315	        return (int) this.clinicService.findAllOwners().stream()
316	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
317	            .count();
318	    }
319	
320	    /**
321	     * The effective registration date to store for a new owner: the date supplied on the request
322	     * when present, otherwise the current server date, in either case rolled forward to a business
323	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
324	     * This single point of resolution is what every registration-date-derived value (the stored
325	     * date, the membership number's year segment, the per-day create-limit) is computed from.
326	     */
327	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
328	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
329	        return toBusinessDay(date);
330	    }
331	
332	    /**
333	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
334	     * following Monday; a weekday is returned unchanged.
335	     */
336	    private static LocalDate toBusinessDay(LocalDate date) {
337	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
338	            date = date.plusDays(1);
339	        }
340	        return date;
341	    }
342	
343	    /**
344	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
345	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
346	     */
347	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
348	        String yy = String.format("%02d", registrationDate.getYear() % 100);
349	        return customerCode + "-M" + yy;
350	    }
