352	    /**
353	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
354	     * last name, compared case-insensitively.
355	     */
356	    private int countNamesakes(Owner owner) {
357	        String firstName = normalizeHouseholdField(owner.getFirstName());
358	        String lastName = normalizeHouseholdField(owner.getLastName());
359	        return (int) this.clinicService.findAllOwners().stream()
360	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
361	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
362	            .count();
363	    }
364	
365	    /** The number of existing owners whose registration date is {@code date}. */
366	    private int countOwnersRegisteredOn(LocalDate date) {
367	        return (int) this.clinicService.findAllOwners().stream()
368	            .filter(existing -> date.equals(existing.getRegistrationDate()))
369	            .count();
370	    }
