372	    /** Whether any existing owner already uses the given (E.164) telephone number. */
373	    private boolean isTelephoneInUse(String telephone) {
374	        return this.clinicService.findAllOwners().stream()
375	            .map(Owner::getTelephone)
376	            .filter(existing -> existing != null)
377	            .map(OwnerRestControllerV1::normalizeTelephone)
378	            .filter(existing -> existing != null)
379	            .anyMatch(telephone::equals);
380	    }
