382	    /** Common street-type abbreviations expanded during address normalization. */
383	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
384	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
385	
386	    /**
387	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
388	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
389	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
390	     * string when {@code address} is null or blank after normalization.
391	     */
392	    private static String normalizeAddress(String address) {
393	        if (address == null) {
394	            return "";
395	        }
396	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
397	        if (collapsed.isEmpty()) {
398	            return "";
399	        }
400	        StringBuilder sb = new StringBuilder(collapsed.length());
401	        for (String token : collapsed.split(" ")) {
402	            if (sb.length() > 0) {
403	                sb.append(' ');
404	            }
405	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
406	        }
407	        return sb.toString();
408	    }
409	
410	    /**
411	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
412	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
413	     */
414	    private static String normalizeHouseholdField(String value) {
415	        if (value == null) {
416	            return "";
417	        }
418	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
419	    }
420	
421	    /**
422	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
423	     * same address compared case-insensitively with collapsed whitespace.
424	     */
425	    private List<Owner> findHousemates(Owner owner) {
426	        String lastName = normalizeHouseholdField(owner.getLastName());
427	        String address = normalizeHouseholdField(owner.getAddress());
428	        return this.clinicService.findAllOwners().stream()
429	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
430	                && normalizeHouseholdField(existing.getAddress()).equals(address))
431	            .toList();
432	    }
433	
434	    /**
435	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
436	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
437	     */
438	    private boolean isHouseholdInUse(Owner owner) {
439	        return !findHousemates(owner).isEmpty();
440	    }
441	
442	    /**
443	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
444	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
445	     * deterministically from those normalized fields so housemates always resolve to the same value,
446	     * regardless of registration order.
447	     */
448	    private static String householdId(Owner owner) {
449	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
450	            + normalizeHouseholdField(owner.getAddress());
451	        try {
452	            byte[] digest = MessageDigest.getInstance("SHA-256")
453	                .digest(key.getBytes(StandardCharsets.UTF_8));
454	            StringBuilder sb = new StringBuilder(24);
455	            for (int i = 0; i < 12; i++) {
456	                sb.append(String.format("%02X", digest[i]));
457	            }
458	            return sb.toString();
459	        }
460	        catch (NoSuchAlgorithmException e) {
461	            throw new IllegalStateException("SHA-256 not available", e);
462	        }
463	    }

